<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_admin();require_once __DIR__.'/../includes/db.php';
$bookings=$conn->query("SELECT sb.*,s.title,owner.F_name AS owner_first,owner.L_name AS owner_last,learner.F_name AS learner_first,learner.L_name AS learner_last,r.booking_id AS reviewed FROM `SESSION_BOOKING` sb JOIN `SKILL` s ON s.skill_id=sb.skill_id JOIN `USER` owner ON owner.user_id=s.user_id JOIN `USER` learner ON learner.user_id=sb.bookedByUser LEFT JOIN `REVIEW` r ON r.booking_id=sb.booking_id ORDER BY sb.session_slot DESC")->fetch_all(MYSQLI_ASSOC);
$pageTitle='Manage bookings';require __DIR__.'/../includes/header.php';
?>
<section class="py-4 py-lg-5"><div class="container"><div class="mb-4"><div class="eyebrow text-primary mb-1">Session operations</div><h1 class="section-title h2">Bookings</h1></div><div class="surface-card overflow-hidden"><?php if(!$bookings):?><div class="empty-state">No bookings yet.</div><?php else:?><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Skill</th><th>Learner</th><th>Mentor</th><th>When</th><th>Session</th><th>Payment</th><th></th></tr></thead><tbody><?php foreach($bookings as $row):?><tr><td class="fw-semibold"><?=e($row['title'])?></td><td><?=e(trim($row['learner_first'].' '.$row['learner_last']))?></td><td><?=e(trim($row['owner_first'].' '.$row['owner_last']))?></td><td><?=e(format_datetime($row['session_slot']))?></td><td><span class="badge text-bg-<?=e(status_class($row['session_status']))?>"><?=e($row['session_status'])?></span></td><td><?=e($row['payment_status']?:'unpaid')?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?=e(url('student/booking_details.php?id='.(int)$row['booking_id']))?>">Manage</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div></section>
<?php require __DIR__.'/../includes/footer.php';?>
